//! Independent manual Crafting conservation and authoritative action tests at66.
use gielinor_world::{grinding,tool_crafting::{Job,Recipe},inventory::{Inventory,Catalog,Item,StackType},stats::Stats,npc::RandomSource,simulation::{World,PlayerData,ActorId,WorldEvent,Action},held_use::{Handler,Scope,Type,Request},hits::{Hit,Target,Style},CoordGrid};
struct NoDraw;impl RandomSource for NoDraw{fn below(&mut self,_:u32)->u32{panic!("manual sinew must not draw RNG")}}
fn recipe()->Recipe{Recipe{exchange:grinding::Recipe{tool:946,input:19665,output:9436,members:true,animation:Some(10937)},level:10,xp_tenths:150,ticks:1,name:"sinew",action:"cut",failure:None}}
fn fixture(slot:usize,case:usize)->(Inventory,Stats){let mut inv=Inventory::new(28,StackType::Normal,false);for s in 0..28{inv.restore_slot(s,Some(Item{id:1931,count:1,vars:0})).unwrap();}for s in[0,1]{inv.restore_slot(s,Some(Item{id:946,count:1,vars:0})).unwrap();}let duplicate=if slot==4{9}else{4};for s in[slot,duplicate]{inv.restore_slot(s,Some(Item{id:19665,count:1,vars:0})).unwrap();}let coin=(2..28).find(|&s|s!=slot && s!=duplicate).unwrap();inv.restore_slot(coin,Some(Item{id:995,count:1000,vars:0})).unwrap();let(base,current,fine)=[(9,9,9690),(9,10,9690),(10,10,11540),(99,9,130344311),(99,10,130344311),(99,99,130344311)][case];let mut stats=Stats::default();stats.set_base(3,10);stats.set_current(3,10);stats.set_base(12,base);stats.set_current(12,current);stats.set_fine_xp(12,fine).unwrap();(inv,stats)}
fn world(slot:usize,case:usize,reverse:bool,member:bool,rate:i32)->(World,ActorId,Request){let(inv,stats)=fixture(slot,case);let mut w=World::default();w.collision.allocate(3200,3200,0);let mut d=PlayerData::new(1,"Independent manual sinew".into(),CoordGrid::new(3200,3200,0).unwrap(),stats);d.inventory=inv;d.xp_rate_hundreds=rate;w.queue_login(1,d).unwrap();w.tick().unwrap();let a=w.actors().next().unwrap();w.set_membership(a,member).unwrap();for id in[946,19665]{w.held_use_types.insert(id,Type{id,content:-1});}w.held_use_handlers.register(Scope::Types,946,19665,Handler::ToolCrafting(recipe())).unwrap();w.drain_events();let h=if reverse{Request{selected_slot:slot as i32,selected_id:19665,target_slot:0,target_id:946}}else{Request{selected_slot:0,selected_id:946,target_slot:slot as i32,target_id:19665}};(w,a,h)}
#[test]
fn twelve_hundred_forty_eight_selected_slot_current_level_member_rate_cases_are_atomic_without_rng(){let mut cases=0;for slot in 2..28{for case in 0..6{for member in[false,true]{for rate in[0,100,125,500]{let(inv,stats)=fixture(slot,case);let before=(inv.clone(),stats.clone());let r=Job{recipe:recipe(),tool_slot:0,input_slot:slot}.resolve(&inv,&Catalog::default(),&stats,rate,member,&mut NoDraw);if member && stats.current(12)>=10 && rate>0{let(p,good)=r.unwrap();assert!(good);let mut expected=inv.clone();expected.restore_slot(slot,Some(Item{id:9436,count:1,vars:0})).unwrap();let mut xp=stats.clone();xp.set_fine_xp(12,stats.fine_xp(12)+150*rate/100).unwrap();assert_eq!(p.inventory,expected);assert_eq!(p.stats,xp);assert!(p.advancement.is_some());}else{assert!(r.is_err());}assert_eq!((inv,stats),before);cases+=1;}}}}assert_eq!(cases,1248);}
#[test]
fn three_hundred_eighty_four_real_world_held_routes_match_one_shot_timing_and_whole_state(){let mut cases=0;for slot in[2,4,17,26]{for case in 0..6{for reverse in[false,true]{for member in[false,true]{for rate in[0,100,125,500]{let(mut w,a,h)=world(slot,case,reverse,member,rate);let before=w.data(a).unwrap().clone();let good=member && before.stats.current(12)>=10 && rate>0;let start=w.clock.0;w.prepare_held_use(a,h).unwrap();w.finish_held_use(a,h).unwrap();assert_eq!(w.data(a).unwrap().inventory,before.inventory);assert!(w.take_tool_crafting_request(a).unwrap().is_none());w.tick_with_random(&mut NoDraw).unwrap();assert_eq!(w.data(a).unwrap().inventory,before.inventory);assert_eq!(w.data(a).unwrap().stats,before.stats);w.tick_with_random(&mut NoDraw).unwrap();assert_eq!(w.clock.0-start,2);let mut inv=before.inventory.clone();let mut stats=before.stats.clone();if good{inv.restore_slot(slot,Some(Item{id:9436,count:1,vars:0})).unwrap();stats.set_fine_xp(12,stats.fine_xp(12)+150*rate/100).unwrap();assert!(w.finish_held_use(a,h).is_err());}for _ in 0..8{w.tick_with_random(&mut NoDraw).unwrap();}assert_eq!(w.data(a).unwrap().inventory,inv);assert_eq!(w.data(a).unwrap().stats,stats);let e=w.drain_events();assert_eq!(e.iter().filter(|e|matches!(e,WorldEvent::SkillAdvanced{..})).count(),usize::from(good));assert_eq!(e.iter().filter(|e|matches!(e,WorldEvent::PlayerCombatAnimation{sequence:10937,..})).count(),usize::from(good));cases+=1;}}}}}assert_eq!(cases,384);}
#[test]
fn thirty_late_guards_and_overlapping_action_cases_cancel_exact_selected_job(){let mut cases=0;for reverse in[false,true]{for mode in 0..15{let(mut w,a,h)=world(17,2,reverse,true,125);w.prepare_held_use(a,h).unwrap();w.finish_held_use(a,h).unwrap();match mode{0=>{w.data_mut(a).unwrap().inventory.restore_slot(17,None).unwrap();},1=>{w.data_mut(a).unwrap().inventory.restore_slot(0,None).unwrap();},2=>{w.data_mut(a).unwrap().inventory.restore_slot(17,Some(Item{id:19665,count:1,vars:1})).unwrap();},3=>{w.data_mut(a).unwrap().inventory.restore_slot(0,Some(Item{id:946,count:1,vars:1})).unwrap();},4=>w.set_membership(a,false).unwrap(),5=>w.data_mut(a).unwrap().stats.set_current(12,9),6=>w.data_mut(a).unwrap().xp_rate_hundreds=0,7=>{w.object_types.dummy.insert(9436);},8=>{w.set_modal_open(a,true).unwrap();w.set_modal_open(a,false).unwrap();},9=>w.submit(a,Action::Walk{destination:CoordGrid::new(3201,3200,0).unwrap(),run:false}).unwrap(),10=>w.request_logout(a).unwrap(),11=>{w.close_dialogs(a).unwrap();},12=>{let fresh=Request{selected_slot:4,selected_id:19665,target_slot:0,target_id:946};w.prepare_held_use(a,fresh).unwrap();w.finish_held_use(a,fresh).unwrap();},13=>{w.queue_hit(Target::Player(a),Hit{display:None,source:None,style:Style::Typeless,damage:20},1).unwrap();w.tick_with_random(&mut NoDraw).unwrap();assert_eq!(w.data(a).unwrap().stats.current(3),0);assert!(w.drain_events().iter().any(|e|matches!(e,WorldEvent::DeathRequested(_))));w.data_mut(a).unwrap().stats.set_current(3,10);},_=>w.data_mut(a).unwrap().stats.set_current(3,0)}let before=w.data(a).unwrap().clone();let mut inv=before.inventory.clone();let mut stats=before.stats.clone();if mode==12{inv.restore_slot(4,Some(Item{id:9436,count:1,vars:0})).unwrap();stats.set_fine_xp(12,stats.fine_xp(12)+187).unwrap();}for _ in 0..10{w.tick_with_random(&mut NoDraw).unwrap();}assert_eq!(w.data(a).unwrap().inventory,inv,"mode{mode}");assert_eq!(w.data(a).unwrap().stats,stats,"mode{mode}");assert_eq!(w.data(a).unwrap().inventory.get(17),before.inventory.get(17));cases+=1;}}assert_eq!(cases,30);}
